#include "../../../kernel/drivers/storage/storage.h"
static uint8_t image[512 * 128];
static int rd(uint64_t lba, uint32_t n, void *p) { if (lba + n > 128) return 0; memcpy(p, image + lba * 512, n * 512U); return 1; }
static int wr(uint64_t lba, uint32_t n, const void *p) { if (lba + n > 128) return 0; memcpy(image + lba * 512, p, n * 512U); return 1; }
static void p16(uint8_t *p, uint16_t v) { p[0] = v >> 8; p[1] = (uint8_t)v; }
static void p32(uint8_t *p, uint32_t v) { p[0] = v >> 24; p[1] = v >> 16; p[2] = v >> 8; p[3] = (uint8_t)v; }
static void p64(uint8_t *p, uint64_t v) { p32(p, v >> 32); p32(p + 4, v); }
int main(void) { memset(image, 0, sizeof(image)); p32(&image[0], 0x58465342); p32(&image[4], 4096); p64(&image[8], 16); p16(&image[102], 512); p32(&image[84], 16); p32(&image[88], 1); p16(&image[100], 4); p16(&image[104], 256); p16(&image[106], 16); image[108] = 12; image[110] = 8; image[111] = 4; image[112] = 4; p64(&image[56], 128); uint8_t *inode = &image[8 * 4096]; p16(inode, 0x494e); p16(&inode[2], 0x4000); inode[4] = 2; inode[5] = 1; p64(&inode[56], 22); inode[100] = 1; inode[101] = 0; p32(&inode[102], 128); inode[106] = 9; p16(&inode[107], 0); p32(&inode[109], 129); memcpy(&inode[113], "hello.txt", 9); uint8_t *file = inode + 256; p16(file, 0x494e); p16(&file[2], 0x8000); file[4] = 2; file[5] = 1; p64(&file[56], 5); memcpy(&file[100], "hello", 5); uint8_t *extent_file = inode + 512; p16(extent_file, 0x494e); p16(&extent_file[2], 0x8000); extent_file[4] = 2; extent_file[5] = 2; p64(&extent_file[56], 5); p32(&extent_file[76], 1); p64(&extent_file[100], 0); p64(&extent_file[108], (9ULL << 21) | 1ULL); memcpy(&image[9 * 4096], "world", 5); storage_initialize(); storage_device_t d = {"xfs", 512, 128, rd, wr}; assert(storage_register(&d)); xfs_fs_t fs; assert(xfs_mount(&fs, 0)); assert(fs.block_size == 4096 && fs.root_inode == 128); uint64_t child = 0, size = 0; char output[6] = {0}; assert(xfs_lookup(&fs, 128, "hello.txt", &child) && child == 129); assert(xfs_inode_size(&fs, child, &size) && size == 5); assert(xfs_read_file(&fs, child, 0, output, 5) && memcmp(output, "hello", 5) == 0); memset(output, 0, sizeof(output)); assert(xfs_read_file(&fs, 130, 0, output, 5) && memcmp(output, "world", 5) == 0); image[0] = 0; assert(!xfs_mount(&fs, 0)); return 0; }
